-- Q04 · O controlo de acesso do staging ficou exatamente igual ao registo P05.
-- Substituir os marcadores __P05_B04/B05/B06/B07__ pelas impressões do P05 (mesma ferramenta/sessão).
-- Só leitura: um único SELECT. Resultado: uma linha por verificação. Se alguma
-- verificação falhar (ou der NULL), a consulta TERMINA EM ERRO com "REPROVADO: <id> obtido=<valor> | …".
WITH pf AS (SELECT p.oid, p.proname::text AS nome, p.pronargs, p.prosrc, p.proacl, p.prorettype FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public'),
c(id, verificacao, ok, esperado, obtido) AS (
  SELECT 'Q04-00'::text, 'marcadores substituídos (4 impressões sha256 do P05)'::text, ('__P05_B04_POLITICAS__' ~ '^[0-9a-f]{64}$' AND '__P05_B05_FUNCOES__' ~ '^[0-9a-f]{64}$' AND '__P05_B06_TABELAS__' ~ '^[0-9a-f]{64}$' AND '__P05_B07_TIPO__' ~ '^[0-9a-f]{64}$')::boolean, 'todos'::text, ('ver cabeçalho do ficheiro')::text
  UNION ALL SELECT 'Q04-01'::text, 'has_staging_access: corpo igual ao da migração 0000 (md5 = constante)'::text, ((SELECT md5(prosrc) FROM pf WHERE nome = 'has_staging_access') = '4376edeea92abf14230207df0fbbef11')::boolean, '4376edeea92abf14230207df0fbbef11'::text, ((SELECT md5(prosrc) FROM pf WHERE nome = 'has_staging_access'))::text
  UNION ALL SELECT 'Q04-02'::text, 'has_role: NÃO substituída (md5 = constante)'::text, ((SELECT md5(prosrc) FROM pf WHERE nome = 'has_role') = '6b9bca1cc09de70841cac113efbdd41a')::boolean, '6b9bca1cc09de70841cac113efbdd41a'::text, ((SELECT md5(prosrc) FROM pf WHERE nome = 'has_role'))::text
  UNION ALL SELECT 'Q04-03'::text, 'políticas de staging_notes/user_roles (USING, WITH CHECK, papéis, comando, tipo) iguais ao P05-B04'::text, (encode(sha256(convert_to((SELECT string_agg(tablename::text || '|' || policyname::text || '|' || permissive::text || '|' || array_to_string(roles, '+') || '|' || cmd::text || '|' || coalesce(qual, '~') || '|' || coalesce(with_check, '~'), E'\n' ORDER BY tablename, policyname) FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('staging_notes', 'user_roles')), 'UTF8')), 'hex') = '__P05_B04_POLITICAS__' AND (SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('staging_notes', 'user_roles')) = 2)::boolean, '= P05-B04'::text, (encode(sha256(convert_to((SELECT string_agg(tablename::text || '|' || policyname::text || '|' || permissive::text || '|' || array_to_string(roles, '+') || '|' || cmd::text || '|' || coalesce(qual, '~') || '|' || coalesce(with_check, '~'), E'\n' ORDER BY tablename, policyname) FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('staging_notes', 'user_roles')), 'UTF8')), 'hex'))::text
  UNION ALL SELECT 'Q04-04'::text, 'atributos de has_role/has_staging_access (SECURITY DEFINER, volatilidade, search_path, dono, permissões, corpo…) iguais ao P05-B05'::text, (encode(sha256(convert_to((SELECT string_agg(p.proname::text || '|' || pg_get_function_identity_arguments(p.oid) || '|' || p.prorettype::regtype::text || '|' || l.lanname::text || '|' || p.prosecdef::text || '|' || p.provolatile::text || '|' || p.proisstrict::text || '|' || p.proleakproof::text || '|' || p.proparallel::text || '|' || coalesce(array_to_string(p.proconfig, ','), '~') || '|' || pg_get_userbyid(p.proowner)::text || '|' || coalesce(p.proacl::text, '~') || '|' || encode(sha256(convert_to(p.prosrc, 'UTF8')), 'hex'), E'\n' ORDER BY p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace JOIN pg_language l ON l.oid = p.prolang WHERE n.nspname = 'public' AND p.proname IN ('has_role', 'has_staging_access')), 'UTF8')), 'hex') = '__P05_B05_FUNCOES__' AND (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace JOIN pg_language l ON l.oid = p.prolang WHERE n.nspname = 'public' AND p.proname IN ('has_role', 'has_staging_access')) = 2)::boolean, '= P05-B05'::text, (encode(sha256(convert_to((SELECT string_agg(p.proname::text || '|' || pg_get_function_identity_arguments(p.oid) || '|' || p.prorettype::regtype::text || '|' || l.lanname::text || '|' || p.prosecdef::text || '|' || p.provolatile::text || '|' || p.proisstrict::text || '|' || p.proleakproof::text || '|' || p.proparallel::text || '|' || coalesce(array_to_string(p.proconfig, ','), '~') || '|' || pg_get_userbyid(p.proowner)::text || '|' || coalesce(p.proacl::text, '~') || '|' || encode(sha256(convert_to(p.prosrc, 'UTF8')), 'hex'), E'\n' ORDER BY p.proname) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace JOIN pg_language l ON l.oid = p.prolang WHERE n.nspname = 'public' AND p.proname IN ('has_role', 'has_staging_access')), 'UTF8')), 'hex'))::text
  UNION ALL SELECT 'Q04-05'::text, 'staging_notes/user_roles: dono, permissões de tabela/coluna, RLS e FORCE RLS iguais ao P05-B06'::text, (encode(sha256(convert_to((SELECT string_agg(c.relname::text || '|' || c.relkind::text || '|' || pg_get_userbyid(c.relowner)::text || '|' || coalesce(c.relacl::text, '~') || '|' || c.relrowsecurity::text || '|' || c.relforcerowsecurity::text || '|' || coalesce((SELECT string_agg(a.attname::text || '=' || a.attacl::text, ',' ORDER BY a.attname) FROM pg_attribute a WHERE a.attrelid = c.oid AND a.attacl IS NOT NULL AND a.attname <> 'created_by'), '~'), E'\n' ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname IN ('staging_notes', 'user_roles')), 'UTF8')), 'hex') = '__P05_B06_TABELAS__' AND (SELECT count(*) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname IN ('staging_notes', 'user_roles')) = 2)::boolean, '= P05-B06'::text, (encode(sha256(convert_to((SELECT string_agg(c.relname::text || '|' || c.relkind::text || '|' || pg_get_userbyid(c.relowner)::text || '|' || coalesce(c.relacl::text, '~') || '|' || c.relrowsecurity::text || '|' || c.relforcerowsecurity::text || '|' || coalesce((SELECT string_agg(a.attname::text || '=' || a.attacl::text, ',' ORDER BY a.attname) FROM pg_attribute a WHERE a.attrelid = c.oid AND a.attacl IS NOT NULL AND a.attname <> 'created_by'), '~'), E'\n' ORDER BY c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname IN ('staging_notes', 'user_roles')), 'UTF8')), 'hex'))::text
  UNION ALL SELECT 'Q04-06'::text, 'app_role: dono e permissões iguais ao P05-B07'::text, (encode(sha256(convert_to((SELECT string_agg(pg_get_userbyid(t.typowner)::text || '|' || coalesce(t.typacl::text, '~') || '|' || t.typtype::text, E'\n') FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace WHERE n.nspname = 'public' AND t.typname = 'app_role'), 'UTF8')), 'hex') = '__P05_B07_TIPO__' AND (SELECT count(*) FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace WHERE n.nspname = 'public' AND t.typname = 'app_role') = 1)::boolean, '= P05-B07'::text, (encode(sha256(convert_to((SELECT string_agg(pg_get_userbyid(t.typowner)::text || '|' || coalesce(t.typacl::text, '~') || '|' || t.typtype::text, E'\n') FROM pg_type t JOIN pg_namespace n ON n.oid = t.typnamespace WHERE n.nspname = 'public' AND t.typname = 'app_role'), 'UTF8')), 'hex'))::text
  UNION ALL SELECT 'Q04-07'::text, 'staging_notes: mesmas 3 notas (md5 = constante)'::text, ((SELECT md5(string_agg(title || '|' || body || '|' || synthetic::text, E'\n' ORDER BY title COLLATE "C")) FROM public.staging_notes) = '9839c85692f965b4f419fb33c6af3404' AND (SELECT count(*) FROM public.staging_notes) = 3)::boolean, '3 / 9839c85692f965b4f419fb33c6af3404'::text, ((SELECT count(*) FROM public.staging_notes)::text || ' / ' || (SELECT md5(string_agg(title || '|' || body || '|' || synthetic::text, E'\n' ORDER BY title COLLATE "C")) FROM public.staging_notes))::text
  UNION ALL SELECT 'Q04-08'::text, 'políticas de staging_notes e user_roles = só as 2 originais (sem barreira V2 nem políticas de admin V2)'::text, (coalesce((SELECT string_agg(tablename::text || '.' || policyname::text || ':' || cmd::text || ':' || permissive::text || ':' || array_to_string(roles, '+'), ',' ORDER BY tablename, policyname) FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('staging_notes', 'user_roles')), '') = 'staging_notes.Staging members read notes:SELECT:PERMISSIVE:authenticated,user_roles.Users read own roles:SELECT:PERMISSIVE:authenticated')::boolean, 'staging_notes.Staging members read notes:SELECT:PERMISSIVE:authenticated,user_roles.Users read own roles:SELECT:PERMISSIVE:authenticated'::text, ((SELECT string_agg(tablename::text || '.' || policyname::text || ':' || cmd::text || ':' || permissive::text || ':' || array_to_string(roles, '+'), ',' ORDER BY tablename, policyname) FROM pg_policies WHERE schemaname = 'public' AND tablename IN ('staging_notes', 'user_roles')))::text
  UNION ALL SELECT 'Q04-09'::text, 'user_roles: colunas id,user_id,role,created_at,created_by'::text, ((SELECT string_agg(a.attname::text, ',' ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid = to_regclass('public.user_roles') AND a.attnum > 0 AND NOT a.attisdropped) = 'id,user_id,role,created_at,created_by')::boolean, 'id,user_id,role,created_at,created_by'::text, ((SELECT string_agg(a.attname::text, ',' ORDER BY a.attnum) FROM pg_attribute a WHERE a.attrelid = to_regclass('public.user_roles') AND a.attnum > 0 AND NOT a.attisdropped))::text
  UNION ALL SELECT 'Q04-10'::text, 'user_roles.created_by: uuid, nulo, sem valor por omissão, sem permissão de coluna'::text, (EXISTS (SELECT 1 FROM pg_attribute a WHERE a.attrelid = to_regclass('public.user_roles') AND a.attname = 'created_by' AND a.atttypid = 'uuid'::regtype AND NOT a.attnotnull AND NOT a.atthasdef AND a.attacl IS NULL))::boolean, 'sim'::text, ((SELECT format_type(a.atttypid, a.atttypmod) || ' notnull=' || a.attnotnull::text || ' default=' || a.atthasdef::text || ' acl=' || coalesce(a.attacl::text, '-') FROM pg_attribute a WHERE a.attrelid = to_regclass('public.user_roles') AND a.attname = 'created_by'))::text
  UNION ALL SELECT 'Q04-11'::text, 'user_roles: restrições inalteradas (sem chave nova)'::text, ((SELECT string_agg(x.conname::text, ',' ORDER BY x.conname COLLATE "C") FROM pg_constraint x WHERE x.conrelid = to_regclass('public.user_roles') AND x.contype <> 'n') = 'user_roles_pkey,user_roles_user_id_fkey,user_roles_user_id_role_key')::boolean, 'user_roles_pkey,user_roles_user_id_fkey,user_roles_user_id_role_key'::text, ((SELECT string_agg(x.conname::text, ',' ORDER BY x.conname COLLATE "C") FROM pg_constraint x WHERE x.conrelid = to_regclass('public.user_roles') AND x.contype <> 'n'))::text
  UNION ALL SELECT 'Q04-12'::text, 'app_role = admin,tester,consultant,support_admin,super_admin'::text, ((SELECT string_agg(e.enumlabel::text, ',' ORDER BY e.enumsortorder) FROM pg_enum e JOIN pg_type ty ON ty.oid = e.enumtypid JOIN pg_namespace n ON n.oid = ty.typnamespace WHERE n.nspname = 'public' AND ty.typname = 'app_role') = 'admin,tester,consultant,support_admin,super_admin')::boolean, 'admin,tester,consultant,support_admin,super_admin'::text, ((SELECT string_agg(e.enumlabel::text, ',' ORDER BY e.enumsortorder) FROM pg_enum e JOIN pg_type ty ON ty.oid = e.enumtypid JOIN pg_namespace n ON n.oid = ty.typnamespace WHERE n.nspname = 'public' AND ty.typname = 'app_role'))::text
),
v AS (SELECT count(*) AS n, string_agg(id || ' obtido=' || left(coalesce(obtido, 'NULL'), 160), ' | ' ORDER BY id) FILTER (WHERE ok IS NOT TRUE) AS falhas FROM c)
SELECT c.id, c.verificacao, CASE WHEN c.ok IS TRUE THEN 'OK' ELSE 'FALHA' END AS estado, c.esperado, c.obtido,
       CASE WHEN v.n <> 13 THEN ('VEREDITO INVÁLIDO: ' || v.n::text || ' verificações')::int::text
            WHEN v.falhas IS NULL THEN 'APROVADO'
            ELSE ('REPROVADO: ' || v.falhas)::int::text END AS veredito
  FROM c CROSS JOIN v ORDER BY c.id;
